use std::{process::{Command,Stdio},io::Read};
#[test]fn headless_delivers_settled_job_followup_before_exit(){let d=tempfile::tempdir().unwrap();let project=d.path().join("proj");std::fs::create_dir(&project).unwrap();let cfg=d.path().join("rig.toml");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"bash\",\"args\":{\"description\":\"Idle probe\",\"command\":\"sleep .2; printf idle-pipe-finished\",\"run_in_background\":true}}\n{\"tool\":\"job_list\",\"args\":{}}\n").unwrap();let mut child=Command::new(env!("CARGO_BIN_EXE_hs-repl")).args(["run","--goal","Start idle probe","--config",cfg.to_str().unwrap(),"--dir",d.path().join("run").to_str().unwrap(),"--project-dir",project.to_str().unwrap(),"--max-steps","1"]).env("HS_SEQMODEL_SCRIPT",script).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();drop(child.stdin.take());let mut text=String::new();child.stdout.take().unwrap().read_to_string(&mut text).unwrap();let status=child.wait().unwrap();assert_eq!(status.code(),Some(1),"followup must not fabricate successful close");let count=text.lines().filter_map(|l|serde_json::from_str::<serde_json::Value>(l).ok()).filter(|v|v["outcome"].is_string()).count();assert_eq!(count,2,"{text}");}
